// Terminal raw mode using libc-style syscalls through Rust standard library
// We use the /dev/tty approach for proper terminal handling

pub struct RawTerminal {
    old_termios: [u8; 60], // termios struct storage
}

impl RawTerminal {
    pub fn new() -> io::Result<Self> {
        let mut old = [0u8; 60];
        // Save current terminal settings
        unsafe {
            let fd = 0i32; // stdin
            if libc_tcgetattr(fd, old.as_mut_ptr()) != 0 {
                return Err(io::Error::last_os_error());
            }
