            cfmakeraw(new.as_mut_ptr());
            if libc_tcsetattr(0, 0, new.as_ptr()) != 0 {
                return Err(io::Error::last_os_error());
            }
        }
        Ok(RawTerminal { old_termios: old })
    }
}

impl Drop for RawTerminal {
    fn drop(&mut self) {
        unsafe {
            libc_tcsetattr(0, 0, self.old_termios.as_ptr());
        }
    }
}

