cat > thokr_impl/src/main.rs << 'RUST_EOF'
mod data;
mod terminal;
mod app;
mod ui;
mod sentences;

use std::env;

fn main() {
    let args: Vec<String> = env::args().collect();

    // Parse arguments
    let config = match parse_args(&args) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    };

    if config.help {
        print_help(&args[0]);
        return;
    }

    if config.version {
        println!("thokr 0.4.1");
        return;
    }

    // Run the app
    app::run(config);
}

#[derive(Debug, Clone)]
pub struct Config {
    pub words: usize,
    pub secs: Option<f64>,
    pub language: Language,
    pub prompt: Option<String>,
    pub sentences: Option<usize>,
    pub help: bool,
    pub version: bool,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Language {
    English,
    English1k,
    English10k,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            words: 15,
            secs: None,
            language: Language::English,
            prompt: None,
            sentences: None,
            help: false,
            version: false,
        }
    }
}

fn parse_args(args: &[String]) -> Result<Config, String> {
    let mut config = Config::default();
    let mut i = 1;

    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => {
                config.help = true;
                return Ok(config);
            }
            "-V" | "--version" => {
                config.version = true;
                return Ok(config);
            }
            "-w" | "--number-of-words" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("error: The argument '{}' requires a value but none was supplied", args[i-1]));
                }
                config.words = args[i].parse::<usize>()
                    .map_err(|_| format!("error: Invalid value '{}' for '--number-of-words'", args[i]))?;
            }
            "-s" | "--number-of-secs" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("error: The argument '{}' requires a value but none was supplied", args[i-1]));
                }
                config.secs = Some(args[i].parse::<f64>()
                    .map_err(|_| format!("error: Invalid value '{}' for '--number-of-secs'", args[i]))?);
            }
            "-l" | "--supported-language" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("error: The argument '{}' requires a value but none was supplied", args[i-1]));
                }
                config.language = match args[i].as_str() {
                    "english" => Language::English,
                    "english1k" => Language::English1k,
                    "english10k" => Language::English10k,
                    v => return Err(format!("error: '{}' isn't a valid value for '--supported-language <SUPPORTED_LANGUAGE>'\n\t[possible values: english, english1k, english10k]", v)),
                };
            }
            "-p" | "--prompt" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("error: The argument '{}' requires a value but none was supplied", args[i-1]));
                }
                config.prompt = Some(args[i].clone());
            }
            "-f" | "--full-sentences" => {
                i += 1;
                if i >= args.len() {
                    return Err(format!("error: The argument '{}' requires a value but none was supplied", args[i-1]));
                }
                config.sentences = Some(args[i].parse::<usize>()
                    .map_err(|_| format!("error: Invalid value '{}' for '--full-sentences'", args[i]))?);
            }
            arg => {
                return Err(format!("error: unexpected argument '{}' found", arg));
            }
        }
        i += 1;
    }

    Ok(config)
}

fn print_help(prog: &str) {
    let name = std::path::Path::new(prog)
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or(prog);
    println!("thokr 0.4.1");
    println!("sleek typing tui with visualized results and historical logging");
    println!();
    println!("USAGE:");
    println!("    {} [OPTIONS]", name);
    println!();
    println!("OPTIONS:");
    println!("    -f, --full-sentences <NUMBER_OF_SENTENCES>");
    println!("            number of sentences to use in test");
    println!();
    println!("    -h, --help");
    println!("            Print help information");
    println!();
    println!("    -l, --supported-language <SUPPORTED_LANGUAGE>");
    println!("            language to pull words from [default: english] [possible values: english, english1k,");
    println!("            english10k]");
    println!();
    println!("    -p, --prompt <PROMPT>");
    println!("            custom prompt to use");
    println!();
    println!("    -s, --number-of-secs <NUMBER_OF_SECS>");
    println!("            number of seconds to run test");
    println!();
    println!("    -V, --version");
    println!("            Print version information");
    println!();
    println!("    -w, --number-of-words <NUMBER_OF_WORDS>");
    println!("            number of words to use in test [default: 15]");
}
RUST_EOF

