use std::io::{self, Read, Write, BufWriter};
use std::time::Duration;

// Raw terminal implementation using libc via FFI
#[repr(C)]
struct Termios {
    c_iflag: u32,
    c_oflag: u32,
    c_cflag: u32,
    c_lflag: u32,
    c_line: u8,
    c_cc: [u8; 32],
    c_ispeed: u32,
    c_ospeed: u32,
}

extern "C" {
    fn tcgetattr(fd: i32, termios_p: *mut Termios) -> i32;
    fn tcsetattr(fd: i32, optional_actions: i32, termios_p: *const Termios) -> i32;
}

const TCSANOW: i32 = 0;
const ECHO: u32 = 0o0010;
const ICANON: u32 = 0o0002;
const ISIG: u32 = 0o0001;
const IEXTEN: u32 = 0o0100000;
const IXON: u32 = 0o0002000;
const ICRNL: u32 = 0o0000400;
const OPOST: u32 = 0o0000001;

pub struct RawMode {
    old_termios: Termios,
}

impl RawMode {
    pub fn enable() -> io::Result<Self> {
        let mut old = Termios {
            c_iflag: 0, c_oflag: 0, c_cflag: 0, c_lflag: 0,
            c_line: 0, c_cc: [0u8; 32], c_ispeed: 0, c_ospeed: 0,
        };
        unsafe {
            if tcgetattr(0, &mut old) != 0 {
                return Err(io::Error::last_os_error());
            }
        }
        let mut raw = Termios {
            c_iflag: old.c_iflag & !(IXON | ICRNL),
            c_oflag: old.c_oflag & !OPOST,
            c_cflag: old.c_cflag,
            c_lflag: old.c_lflag & !(ECHO | ICANON | ISIG | IEXTEN),
            c_line: old.c_line,
            c_cc: old.c_cc,
            c_ispeed: old.c_ispeed,
            c_ospeed: old.c_ospeed,
        };
        // VMIN=0, VTIME=1 (100ms timeout)
        raw.c_cc[6] = 0;  // VMIN
        raw.c_cc[5] = 1;  // VTIME (deciseconds)
        unsafe {
            if tcsetattr(0, TCSANOW, &raw) != 0 {
                return Err(io::Error::last_os_error());
            }
        }
        Ok(RawMode { old_termios: old })
    }
}

impl Drop for RawMode {
    fn drop(&mut self) {
        unsafe {
            tcsetattr(0, TCSANOW, &self.old_termios);
        }
    }
}

pub fn get_terminal_size() -> (u16, u16) {
    #[repr(C)]
    struct WinSize {
        ws_row: u16,
        ws_col: u16,
        ws_xpixel: u16,
        ws_ypixel: u16,
    }

    extern "C" {
        fn ioctl(fd: i32, request: u64, ...) -> i32;
    }

    const TIOCGWINSZ: u64 = 0x5413;
    let mut ws = WinSize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
    unsafe {
        ioctl(1, TIOCGWINSZ, &mut ws as *mut WinSize);
    }
    (ws.ws_col, ws.ws_row)
}

pub fn read_key() -> Option<Key> {
    let mut buf = [0u8; 8];
    let n = unsafe {
        libc_read(0, buf.as_mut_ptr() as *mut std::ffi::c_void, 8)
    };
    if n <= 0 {
        return None;
    }

    let bytes = &buf[..n as usize];
    match bytes {
        [27, b'[', b'A'] => Some(Key::Up),
        [27, b'[', b'B'] => Some(Key::Down),
        [27, b'[', b'C'] => Some(Key::Right),
        [27, b'[', b'D'] => Some(Key::Left),
        [27] => Some(Key::Escape),
        [127] | [8] => Some(Key::Backspace),
        [13] | [10] => Some(Key::Enter),
        [c] if *c >= 32 => Some(Key::Char(*c as char)),
        _ => None,
    }
}

extern "C" {
    fn read(fd: i32, buf: *mut std::ffi::c_void, count: usize) -> isize;
}

fn libc_read(fd: i32, buf: *mut std::ffi::c_void, count: usize) -> isize {
    unsafe { read(fd, buf, count) }
}

#[derive(Debug, Clone)]
pub enum Key {
    Char(char),
    Backspace,
    Enter,
    Left,
    Right,
    Up,
    Down,
    Escape,
}

pub struct Screen {
    stdout: BufWriter<io::Stdout>,
}

impl Screen {
    pub fn new() -> Self {
        let mut s = Screen {
            stdout: BufWriter::new(io::stdout()),
        };
        // Enter alternate screen, hide cursor
        let _ = s.write_str("\x1b[?1049h\x1b[?25l");
        s
    }

    pub fn write_str(&mut self, s: &str) {
        let _ = self.stdout.write_all(s.as_bytes());
    }

    pub fn flush(&mut self) {
        let _ = self.stdout.flush();
    }

    pub fn clear(&mut self) {
        self.write_str("\x1b[2J\x1b[H");
    }

    pub fn move_to(&mut self, row: u16, col: u16) {
        let s = format!("\x1b[{};{}H", row, col);
        self.write_str(&s);
    }

    pub fn set_green(&mut self) {
        self.write_str("\x1b[32m");
    }

    pub fn set_red(&mut self) {
        self.write_str("\x1b[31m");
    }

    pub fn set_normal(&mut self) {
        self.write_str("\x1b[0m");
    }

    pub fn set_underline(&mut self) {
        self.write_str("\x1b[4m");
    }
}

impl Drop for Screen {
    fn drop(&mut self) {
        // Exit alternate screen, show cursor
        let _ = self.stdout.write_all(b"\x1b[?1049l\x1b[?25h");
        let _ = self.stdout.flush();
    }
}
