fn render_text_line(
    screen: &mut Screen,
    line: &str,
    line_offset: usize,
    typed: &[String],
    current_input: &str,
    words: &[String],
) {
    // Calculate the cumulative char position
    // Build the expected text
    let mut expected_chars: Vec<char> = Vec::new();
    for (i, word) in words.iter().enumerate() {
        for c in word.chars() {
            expected_chars.push(c);
        }
        if i < words.len() - 1 {
            expected_chars.push(' ');
        }
    }

    // Build typed chars with correct/wrong indicators
    let mut actual_typed: Vec<char> = Vec::new();
    for (i, tw) in typed.iter().enumerate() {
        for c in tw.chars() {
            actual_typed.push(c);
        }
        if i < typed.len() - 1 || !current_input.is_empty() {
            actual_typed.push(' ');
        }
    }
    for c in current_input.chars() {
        actual_typed.push(c);
    }

    // Render the line
    for (i, c) in line.chars().enumerate() {
        let pos = line_offset + i;
        if pos < actual_typed.len() {
            // This char has been typed
            if pos < expected_chars.len() && actual_typed[pos] == expected_chars[pos] {
                screen.set_green();
            } else {
                screen.set_red();
            }
            screen.write_str(&c.to_string());
            screen.set_normal();
        } else if pos == actual_typed.len() {
            // Cursor position
            screen.set_underline();
            screen.write_str(&c.to_string());
            screen.set_normal();
        } else {
            screen.write_str(&c.to_string());
        }
    }
}

fn wrap_text(text: &str, max_width: usize) -> Vec<String> {
    if max_width == 0 {
        return vec![text.to_string()];
    }

    let mut lines: Vec<String> = Vec::new();
    let mut current_line = String::new();

    for word in text.split(' ') {
        if current_line.is_empty() {
            current_line = word.to_string();
        } else if current_line.len() + 1 + word.len() <= max_width {
            current_line.push(' ');
            current_line.push_str(word);
        } else {
            lines.push(current_line);
            current_line = word.to_string();
        }
    }
    if !current_line.is_empty() {
        lines.push(current_line);
    }

    lines
}

// Helper trait for string padding
trait StrExt {
    fn ljust(&self, width: usize) -> String;
}

impl StrExt for str {
    fn ljust(&self, width: usize) -> String {
        if self.len() >= width {
            self.to_string()
        } else {
            format!("{}{}", self, " ".repeat(width - self.len()))
        }
    }
}

impl StrExt for String {
    fn ljust(&self, width: usize) -> String {
        self.as_str().ljust(width)
    }
}
