const BRAILLE_BASE: u32 = 0x2800;

// Map from (col, row) to bit position
// col = 0 (left) or 1 (right)
// row = 0 (top) to 3 (bottom)
fn dot_bit(col: usize, row: usize) -> u8 {
    match (col, row) {
        (0, 0) => 0,
        (0, 1) => 1,
        (0, 2) => 2,
        (1, 0) => 3,
        (1, 1) => 4,
        (1, 2) => 5,
        (0, 3) => 6,
        (1, 3) => 7,
        _ => 0,
    }
}

fn braille_char(dots: u8) -> char {
    char::from_u32(BRAILLE_BASE + dots as u32).unwrap_or(' ')
}

pub struct Canvas {
    pub width: usize,  // in cells (each cell = 2 pixels wide)
    pub height: usize, // in cells (each cell = 4 pixels tall)
    pub pixels: Vec<Vec<bool>>, // [pixel_y][pixel_x]
}

impl Canvas {
    pub fn new(cell_width: usize, cell_height: usize) -> Self {
        let pw = cell_width * 2;
        let ph = cell_height * 4;
        Canvas {
            width: cell_width,
            height: cell_height,
            pixels: vec![vec![false; pw]; ph],
        }
    }

    fn set_pixel(&mut self, px: usize, py: usize) {
        let ph = self.height * 4;
        let pw = self.width * 2;
        if px < pw && py < ph {
            self.pixels[py][px] = true;
        }
    }

    // Draw a line from (x1,y1) to (x2,y2) in pixel coordinates
    // y=0 is BOTTOM, y=height*4-1 is TOP (chart convention)
    pub fn draw_line(&mut self, x1: f64, y1: f64, x2: f64, y2: f64) {
        let ph = (self.height * 4) as f64;
        let pw = (self.width * 2) as f64;

        // Convert to pixel coords (flip y axis)
        let px1 = (x1 * pw).round() as i64;
        let py1 = (ph - 1.0 - y1 * (ph - 1.0)).round() as i64;
        let px2 = (x2 * pw).round() as i64;
        let py2 = (ph - 1.0 - y2 * (ph - 1.0)).round() as i64;

        self.bresenham(px1, py1, px2, py2);
    }

    fn bresenham(&mut self, x0: i64, y0: i64, x1: i64, y1: i64) {
        let dx = (x1 - x0).abs();
        let dy = (y1 - y0).abs();
        let sx: i64 = if x0 < x1 { 1 } else { -1 };
        let sy: i64 = if y0 < y1 { 1 } else { -1 };
        let mut err = dx - dy;
        let mut x = x0;
        let mut y = y0;

        loop {
            if x >= 0 && y >= 0 {
                self.set_pixel(x as usize, y as usize);
            }
            if x == x1 && y == y1 {
                break;
            }
            let e2 = 2 * err;
            if e2 > -dy {
                err -= dy;
                x += sx;
            }
            if e2 < dx {
                err += dx;
                y += sy;
            }
        }
    }

    pub fn render(&self) -> Vec<Vec<char>> {
        let mut result = vec![vec![' '; self.width]; self.height];
        for cell_y in 0..self.height {
            for cell_x in 0..self.width {
                let mut dots = 0u8;
                for row in 0..4usize {
                    for col in 0..2usize {
                        let px = cell_x * 2 + col;
                        let py = cell_y * 4 + row;
                        if py < self.pixels.len() && px < self.pixels[py].len() {
                            if self.pixels[py][px] {
                                dots |= 1 << dot_bit(col, row);
                            }
                        }
                    }
                }
                result[cell_y][cell_x] = braille_char(dots);
            }
        }
        result
    }
