                        let px = cell_x * 2 + col;
                        let py = cell_y * 4 + row;
                        if py < self.pixels.len() && px < self.pixels[py].len() {
                            if self.pixels[py][px] {
                                dots |= 1 << dot_bit(col, row);
                            }
                        }
                    }
                }
                result[cell_y][cell_x] = braille_char(dots);
            }
        }
        result
    }
}

// Render the results chart
pub fn render_chart(
    screen: &mut Screen,
    data: &[(f64, f64)], // (time, wpm) pairs
    term_width: u16,
    term_height: u16,
    wpm: u64,
    acc: u64,
    sd: f64,
) {
    let tw = term_width as usize;
    let th = term_height as usize;

    // Calculate layout
    let max_wpm = if data.is_empty() {
        0
    } else {
        data.iter().map(|(_, w)| *w as u64).max().unwrap_or(0)
    };

    let max_wpm_str = if max_wpm == u64::MAX || data.is_empty() {
        "inf".to_string()
    } else {
        format!("{}", max_wpm)
    };

    // Y-axis prefix width: 5 spaces + max_wpm_str.len() chars + │
    let y_label_width = 5 + max_wpm_str.len();
    let chart_width = if tw > y_label_width + 1 { tw - y_label_width - 1 } else { 1 };

    // Chart spans rows 3 to (th-7) inclusive
    // Inner data area: rows 4 to (th-8) = chart_inner_height
    // Row 3: top label (max_wpm│wpm)
    // Row th-7: bottom label (0│  seconds...)
    // Row th-6: └─────
    // Row th-5: x-axis labels
    // Row th-4: blank
    // Row th-3: summary
    // Row th-2: blank  
    // Row th-1: keys

    let chart_data_height = if th > 9 { th - 9 } else { 1 }; // inner area height in cells
    let chart_total_rows = th - 7; // rows 3 to th-7 inclusive

    // Calculate x bounds
    let x_max = if data.is_empty() {
        1.0
    } else {
        let last_x = data.last().unwrap().0;
        (last_x.floor() as i64 + 1) as f64
    };
    let x_min = 1.0;

    // Calculate y bounds
    let y_max = if data.is_empty() || max_wpm == 0 {
        1.0
    } else {
        max_wpm as f64
    };

    // Clear screen
    screen.clear();

    // Render chart rows 3 to th-7
    // First, create the canvas for the data area
    let canvas_height = chart_data_height; // cells
    let canvas_width = chart_width;        // cells

    let mut canvas = Canvas::new(canvas_width, canvas_height);

    // Draw the line through all data points
    if data.len() >= 2 {
        for i in 0..data.len()-1 {
            let (x1, y1) = data[i];
            let (x2, y2) = data[i+1];
            // Normalize to [0,1] for canvas
            let nx1 = (x1 - x_min) / (x_max - x_min);
            let ny1 = if y_max > 0.0 { y1 / y_max } else { 0.0 };
            let nx2 = (x2 - x_min) / (x_max - x_min);
            let ny2 = if y_max > 0.0 { y2 / y_max } else { 0.0 };
            canvas.draw_line(nx1, ny1.min(1.0), nx2, ny2.min(1.0));
        }
    } else if data.len() == 1 {
        let (x1, y1) = data[0];
        let nx1 = (x1 - x_min) / (x_max - x_min);
        let ny1 = if y_max > 0.0 { y1 / y_max } else { 0.0 };
        canvas.draw_line(0.0, ny1.min(1.0), nx1, ny1.min(1.0));
    }

    let chart_chars = canvas.render();

    // Render each chart row
    // Row 3 (1-indexed in terminal): top label + first data row
    let top_prefix = format!("{:>width$}", max_wpm_str, width = y_label_width);
    screen.move_to(3, 1);
    screen.write_str(&top_prefix);
    screen.write_str("│wpm");
    if canvas_height > 0 && !chart_chars.is_empty() {
        // Row 3 corresponds to canvas row 0
        let row_str: String = chart_chars[0].iter().collect();
        screen.write_str(&row_str);
    }

    // Data rows 4 to (th-8) = canvas rows 1 to canvas_height-1
    for row in 1..canvas_height {
        let term_row = (3 + row) as u16;
        screen.move_to(term_row, 1);
        let prefix = " ".repeat(y_label_width);
        screen.write_str(&prefix);
        screen.write_str("│");
        let row_str: String = chart_chars[row].iter().collect();
        screen.write_str(&row_str);
    }

    // Bottom label row (th-7)
    let bot_prefix = format!("{}{}", " ".repeat(5), "0".to_string().ljust(max_wpm_str.len()));
    screen.move_to((th - 7) as u16, 1);
    screen.write_str(&bot_prefix);
    screen.write_str("│");
    // Write "seconds" right-justified
    let seconds_label = "seconds";
    let spaces_before_seconds = if chart_width > seconds_label.len() {
        chart_width - seconds_label.len()
    } else {
        0
    };
    screen.write_str(&" ".repeat(spaces_before_seconds));
    screen.write_str(seconds_label);

    // Separator line (th-6)
    screen.move_to((th - 6) as u16, 1);
    screen.write_str(&" ".repeat(y_label_width));
    screen.write_str("└");
    screen.write_str(&"─".repeat(chart_width));

    // X-axis labels (th-5)
    screen.move_to((th - 5) as u16, 1);
    screen.write_str(&" ".repeat(y_label_width));
    screen.write_str("1");

    let x_max_str = format!("{:.2}", x_max);
    let spaces = if chart_width > x_max_str.len() + 1 {
        chart_width - x_max_str.len() - 1
    } else {
        0
    };
    screen.write_str(&" ".repeat(spaces));
    screen.write_str(&x_max_str);

    // Summary (th-3)
    let wpm_str = if max_wpm == u64::MAX {
        "inf".to_string()
    } else {
        format!("{}", wpm)
    };
    let summary = format!("{} wpm   {}% acc   {:.2} sd", wpm_str, acc, sd);
    let summary_col = if tw > summary.len() { (tw - summary.len()) / 2 + 1 } else { 1 };
    screen.move_to((th - 3) as u16, summary_col as u16);
    screen.write_str(&summary);

    // Keys (th-1)
    screen.move_to((th - 1) as u16, 1);
    screen.write_str("     (r)etry / (n)ew / (esc)ape");

    screen.flush();
}

pub fn render_test(
    screen: &mut Screen,
    words: &[String],
