    current_input: &str,
    timer: Option<f64>,
    term_width: u16,
    term_height: u16,
) {
    let tw = term_width as usize;
    let th = term_height as usize;

    // Build the display line(s)
    // Words are displayed with spaces between them
    // Typed words are shown with color indicators
    // Current word shows typed chars with cursor

    screen.clear();

    // Build word display
    let mut display_words: Vec<String> = Vec::new();
    for (i, word) in words.iter().enumerate() {
        if i < typed.len() {
            // Already typed - show with · separator to indicate progress
            display_words.push(format!("·"));
            // Actually the display uses the word itself followed by ·
            // Let me reconsider...
            display_words.push(word.clone());
        } else {
            display_words.push(word.clone());
        }
    }

    // The display shows words separated by spaces
    // With cursor at current position
    // Words wrap to next line if too long

    // Build lines for display
    let all_words: Vec<&str> = words.iter().map(|s| s.as_str()).collect();
    let full_text = all_words.join(" ");

    // Wrap text to fit terminal width
    let max_width = tw.saturating_sub(4); // Some margin
    let lines = wrap_text(&full_text, max_width);

    // Calculate vertical center
    let start_row = if th > lines.len() {
        (th - lines.len()) / 2 + 1
    } else {
        1
    };

    // Timer display (if secs mode)
    if let Some(remaining) = timer {
        let timer_str = format!("{:.1}", remaining);
        let timer_col = if tw > timer_str.len() { (tw - timer_str.len()) / 2 + 1 } else { 1 };
        screen.move_to((start_row - 2) as u16, timer_col as u16);
        screen.write_str(&timer_str);
    }

    // Current position in the text
    let typed_chars: usize = typed.iter().map(|w| w.len() + 1).sum::<usize>().saturating_sub(
        if typed.is_empty() { 0 } else { 1 }
    );
    let typed_chars = typed_chars + current_input.len();

    // Display the text with colors
    for (line_idx, line) in lines.iter().enumerate() {
        let row = (start_row + line_idx) as u16;
        let col = if tw > line.len() { (tw - line.len()) / 2 + 1 } else { 1 };
        screen.move_to(row, col as u16);

        // Render each character with appropriate color
        let line_start = lines[..line_idx].iter().map(|l| l.len() + 1).sum::<usize>();
        // Actually need to track which chars are typed/correct/wrong
        render_text_line(screen, line, line_start, typed, current_input, words);
    }

    screen.flush();
}

fn render_text_line(
    screen: &mut Screen,
    line: &str,
    line_offset: usize,
    typed: &[String],
    current_input: &str,
    words: &[String],
) {
    // Calculate the cumulative char position
    // Build the expected text
    let mut expected_chars: Vec<char> = Vec::new();
    for (i, word) in words.iter().enumerate() {
        for c in word.chars() {
            expected_chars.push(c);
        }
        if i < words.len() - 1 {
            expected_chars.push(' ');
        }
    }

    // Build typed chars with correct/wrong indicators
    let mut actual_typed: Vec<char> = Vec::new();
    for (i, tw) in typed.iter().enumerate() {
        for c in tw.chars() {
            actual_typed.push(c);
        }
        if i < typed.len() - 1 || !current_input.is_empty() {
            actual_typed.push(' ');
        }
    }
    for c in current_input.chars() {
        actual_typed.push(c);
    }

    // Render the line
    for (i, c) in line.chars().enumerate() {
        let pos = line_offset + i;
        if pos < actual_typed.len() {
            // This char has been typed
            if pos < expected_chars.len() && actual_typed[pos] == expected_chars[pos] {
                screen.set_green();
            } else {
                screen.set_red();
            }
            screen.write_str(&c.to_string());
            screen.set_normal();
        } else if pos == actual_typed.len() {
            // Cursor position
            screen.set_underline();
            screen.write_str(&c.to_string());
            screen.set_normal();
        } else {
            screen.write_str(&c.to_string());
        }
    }
}

fn wrap_text(text: &str, max_width: usize) -> Vec<String> {
    if max_width == 0 {
        return vec![text.to_string()];
    }

    let mut lines: Vec<String> = Vec::new();
    let mut current_line = String::new();

    for word in text.split(' ') {
        if current_line.is_empty() {
            current_line = word.to_string();
        } else if current_line.len() + 1 + word.len() <= max_width {
            current_line.push(' ');
            current_line.push_str(word);
        } else {
            lines.push(current_line);
            current_line = word.to_string();
        }
    }
    if !current_line.is_empty() {
        lines.push(current_line);
    }

    lines
}

// Helper trait for string padding
trait StrExt {
    fn ljust(&self, width: usize) -> String;
}

impl StrExt for str {
    fn ljust(&self, width: usize) -> String {
        if self.len() >= width {
            self.to_string()
        } else {
            format!("{}{}", self, " ".repeat(width - self.len()))
        }
    }
}

impl StrExt for String {
    fn ljust(&self, width: usize) -> String {
        self.as_str().ljust(width)
    }
}
