        let text = sentences::generate_sentences(rng, n);
        return text.split_whitespace().map(|s| s.to_string()).collect();
    }

    let word_list: &[&str] = match config.language {
        Language::English => data::english::WORDS,
        Language::English1k => data::english1k::WORDS,
        Language::English10k => data::english10k::WORDS,
    };

    // Select random words (without immediate repetition)
    let n = config.words;
    let mut indices: Vec<usize> = (0..word_list.len()).collect();
    rng.shuffle(&mut indices);

    indices[..n.min(indices.len())]
        .iter()
        .map(|&i| word_list[i].to_string())
        .collect()
}

enum TestResult {
    Completed {
        wpm: u64,
        acc: u64,
        sd: f64,
        data: Vec<(f64, f64)>,
        elapsed: f64,
    },
    Restart,
    NewPrompt,
    Escape,
}

enum ResultAction {
    Retry,
    New,
    Escape,
}

fn run_test(
    screen: &mut Screen,
    rng: &mut Rng,
    config: &Config,
    words: &[String],
    num_words: usize,
) -> TestResult {
    let (tw, th) = get_terminal_size();

    let mut typed_words: Vec<String> = Vec::new();
    let mut current_input = String::new();
    let mut start_time: Option<Instant> = None;
    let mut word_times: Vec<f64> = Vec::new(); // elapsed when each word completed
    let mut word_correct_counts: Vec<usize> = Vec::new(); // cumulative correct chars
    let mut total_correct_chars = 0usize;
    let mut total_typed_chars = 0usize;

    let timer_secs = config.secs;
    let mut timer_expired = false;

    // Initial render
    render_test_screen(screen, words, &typed_words, &current_input, timer_secs, tw, th);

    let mut last_tick = Instant::now();

    loop {
        // Check timer
        if let Some(secs) = timer_secs {
            if let Some(start) = start_time {
                let elapsed = start.elapsed().as_secs_f64();
                if elapsed >= secs {
                    timer_expired = true;
                }
            }
        }

        if timer_expired {
            // Timer expired, compute results
            break;
        }

        // Read key with timeout
        if let Some(key) = read_key() {
            match key {
                Key::Escape => return TestResult::Escape,
                Key::Left => return TestResult::Restart,
                Key::Right => {
                    if config.prompt.is_none() {
                        return TestResult::NewPrompt;
                    }
                }
                Key::Char(c) => {
                    // Start timer on first key
                    if start_time.is_none() {
                        start_time = Some(Instant::now());
                    }

                    let word_idx = typed_words.len();
                    if word_idx >= words.len() {
                        break;
                    }

                    if c == ' ' {
                        // Complete current word
                        if !current_input.is_empty() || word_idx < words.len() {
                            let expected = &words[word_idx];

                            // Count correct chars in this word
                            let word_correct = count_correct(&current_input, expected);
                            total_correct_chars += word_correct;
                            total_typed_chars += current_input.len();

                            // If not the last word, add space
                            if word_idx < words.len() - 1 {
                                // Space is correct if we're moving to next word
                                total_correct_chars += 1; // space always counts
                                total_typed_chars += 1;
                            }

                            typed_words.push(current_input.clone());

                            // Record word completion time
                            if let Some(start) = start_time {
                                let elapsed = start.elapsed().as_secs_f64();
                                word_times.push(elapsed);
                                word_correct_counts.push(total_correct_chars);
                            }

                            current_input.clear();

                            // Check if this was the last word (completed by space on non-last)
                            if typed_words.len() >= words.len() {
                                break;
                            }
                        }
                    } else {
                        current_input.push(c);

                        // Check if last word is complete (last char of last word)
                        let word_idx = typed_words.len();
                        if word_idx == words.len() - 1 {
                            let expected = &words[word_idx];
                            if current_input.len() == expected.len() {
                                // Last word completed
                                let word_correct = count_correct(&current_input, expected);
                                total_correct_chars += word_correct;
                                total_typed_chars += current_input.len();

                                typed_words.push(current_input.clone());

                                if let Some(start) = start_time {
                                    let elapsed = start.elapsed().as_secs_f64();
                                    word_times.push(elapsed);
                                    word_correct_counts.push(total_correct_chars);
                                }

                                current_input.clear();
                                break;
                            }
                        }
                    }

                    // Re-render
                    let (tw, th) = get_terminal_size();
                    let remaining = timer_secs.map(|secs| {
                        secs - start_time.map(|s| s.elapsed().as_secs_f64()).unwrap_or(0.0)
                    });
                    render_test_screen(screen, words, &typed_words, &current_input, remaining, tw, th);
                }
                Key::Backspace => {
                    if start_time.is_some() {
                        if !current_input.is_empty() {
                            current_input.pop();
                        }
                        let (tw, th) = get_terminal_size();
                        let remaining = timer_secs.map(|secs| {
                            secs - start_time.map(|s| s.elapsed().as_secs_f64()).unwrap_or(0.0)
                        });
                        render_test_screen(screen, words, &typed_words, &current_input, remaining, tw, th);
                    }
                }
                _ => {}
            }
        } else {
            // Timeout - update timer display if needed
            if let (Some(secs), Some(start)) = (timer_secs, start_time) {
                let elapsed = start.elapsed().as_secs_f64();
                let remaining = secs - elapsed;
                if remaining <= 0.0 {
                    timer_expired = true;
                } else {
                    if last_tick.elapsed() >= TICK_RATE {
                        last_tick = Instant::now();
                        let (tw, th) = get_terminal_size();
                        render_test_screen(screen, words, &typed_words, &current_input, Some(remaining.max(0.0)), tw, th);
                    }
                }
            }
        }
    }

    // Compute results
    let elapsed = start_time
        .map(|s| s.elapsed().as_secs_f64())
        .unwrap_or(0.0);

    // Build data series for chart
    let mut chart_data: Vec<(f64, f64)> = Vec::new();
    for (i, &t) in word_times.iter().enumerate() {
        let chars = word_correct_counts[i];
        let x_max = t.floor() as i64 + 1;
        let wpm_at_word = if x_max > 0 {
            ((chars as f64 * 12.0 / x_max as f64).ceil()) as u64
        } else {
            u64::MAX
        };
        chart_data.push((t, wpm_at_word as f64));
    }

    // Final WPM
    let final_x_max = elapsed.floor() as i64 + 1;
    let final_wpm = if final_x_max > 0 && elapsed > 0.001 {
        ((total_correct_chars as f64 * 12.0 / final_x_max as f64).ceil()) as u64
    } else if elapsed <= 0.001 {
        u64::MAX // inf
    } else {
        0
    };

    // Accuracy (percentage of correct chars)
    let acc = if total_typed_chars == 0 {
        100u64
    } else {
        let raw_acc = total_correct_chars as f64 / total_typed_chars as f64 * 100.0;
        raw_acc.round() as u64
    };

    // Std dev (simplified - population std dev of WPM data points)
    let sd = compute_std_dev(&chart_data);

    TestResult::Completed {
        wpm: final_wpm,
        acc,
        sd,
        data: chart_data,
        elapsed,
    }
}

fn count_correct(typed: &str, expected: &str) -> usize {
    typed.chars().zip(expected.chars())
        .filter(|(t, e)| t == e)
        .count()
}

fn compute_std_dev(data: &[(f64, f64)]) -> f64 {
    if data.len() < 2 {
        return 0.0;
    }
    let wpms: Vec<f64> = data.iter().map(|(_, w)| *w).collect();
    let mean = wpms.iter().sum::<f64>() / wpms.len() as f64;
    let var = wpms.iter().map(|w| (w - mean).powi(2)).sum::<f64>() / wpms.len() as f64;
    (var.sqrt() * 100.0).round() / 100.0
}

