    },
    Restart,
    NewPrompt,
    Escape,
}

enum ResultAction {
    Retry,
    New,
    Escape,
}

fn run_test(
    screen: &mut Screen,
    config: &Config,
    words: &[String],
) -> TestResult {
    let (tw, th) = get_terminal_size();

    let mut typed_words: Vec<String> = Vec::new();
    let mut current_input = String::new();
    let mut start_time: Option<Instant> = None;
    let mut word_times: Vec<f64> = Vec::new();
    let mut cum_correct_at_word: Vec<usize> = Vec::new();
    let mut total_correct_chars = 0usize;
    let mut total_typed_chars = 0usize;

    let timer_secs = config.secs;

    // Initial render
    {
        let (tw, th) = get_terminal_size();
        let remaining = timer_secs;
        crate::ui::render_test(screen, words, &typed_words, &current_input, remaining, tw, th);
    }

    let mut last_tick = Instant::now();

    loop {
        // Check timer expiry
        if let (Some(secs), Some(start)) = (timer_secs, start_time) {
            if start.elapsed().as_secs_f64() >= secs {
                break;
            }
        }

        if let Some(key) = read_key() {
            match key {
                Key::Escape => return TestResult::Escape,
                Key::Left => return TestResult::Restart,
                Key::Right => {
                    if config.prompt.is_none() && config.sentences.is_none() {
                        return TestResult::NewPrompt;
                    }
                }
                Key::Char(c) => {
                    if start_time.is_none() {
                        start_time = Some(Instant::now());
                    }

                    let word_idx = typed_words.len();
                    if word_idx >= words.len() {
                        break;
                    }

                    if c == ' ' {
                        let expected = &words[word_idx];

                        // Count correct chars in this word
                        let word_correct = count_correct(&current_input, expected);
                        total_correct_chars += word_correct;
                        total_typed_chars += current_input.len();

                        // Space always counts (correct) if there's a next word
                        if word_idx < words.len() - 1 {
                            total_correct_chars += 1;
                            total_typed_chars += 1;
                        }

                        typed_words.push(current_input.clone());

                        if let Some(start) = start_time {
                            let elapsed = start.elapsed().as_secs_f64();
                            word_times.push(elapsed);
                            cum_correct_at_word.push(total_correct_chars);
                        }

                        current_input.clear();

                        if typed_words.len() >= words.len() {
                            break;
                        }
                    } else {
                        current_input.push(c);

                        // Check if last word completed
                        let word_idx = typed_words.len();
                        if word_idx == words.len() - 1 {
                            let expected = &words[word_idx];
                            if current_input.len() == expected.len() {
                                let word_correct = count_correct(&current_input, expected);
                                total_correct_chars += word_correct;
                                total_typed_chars += current_input.len();

                                typed_words.push(current_input.clone());

                                if let Some(start) = start_time {
                                    let elapsed = start.elapsed().as_secs_f64();
                                    word_times.push(elapsed);
                                    cum_correct_at_word.push(total_correct_chars);
                                }

                                current_input.clear();
                                break;
                            }
                        }
                    }

                    let (tw, th) = get_terminal_size();
                    let remaining = timer_secs.map(|secs| {
                        (secs - start_time.unwrap().elapsed().as_secs_f64()).max(0.0)
                    });
                    crate::ui::render_test(screen, words, &typed_words, &current_input, remaining, tw, th);
                }
                Key::Backspace => {
                    if start_time.is_some() {
                        current_input.pop();
                        let (tw, th) = get_terminal_size();
                        let remaining = timer_secs.map(|secs| {
                            (secs - start_time.unwrap().elapsed().as_secs_f64()).max(0.0)
                        });
                        crate::ui::render_test(screen, words, &typed_words, &current_input, remaining, tw, th);
                    }
                }
                _ => {}
            }
        } else {
            // Timeout - update timer if needed
            if let (Some(secs), Some(start)) = (timer_secs, start_time) {
                let elapsed = start.elapsed().as_secs_f64();
                let remaining = (secs - elapsed).max(0.0);
                if elapsed >= secs {
                    break;
                }
                if last_tick.elapsed().as_millis() >= TICK_RATE_MS as u128 {
                    last_tick = Instant::now();
                    let (tw, th) = get_terminal_size();
                    crate::ui::render_test(screen, words, &typed_words, &current_input, Some(remaining), tw, th);
                }
            }
        }
    }

    let elapsed = start_time
        .map(|s| s.elapsed().as_secs_f64())
        .unwrap_or(0.0);

    // Build chart data
    let mut chart_data: Vec<(f64, f64)> = Vec::new();
    for (i, &t) in word_times.iter().enumerate() {
        let chars = cum_correct_at_word[i];
        let x_max = t.floor() as i64 + 1;
        let wpm_val = if x_max > 0 {
            (chars as f64 * 12.0 / x_max as f64).ceil() as u64
        } else {
            u64::MAX
        };
        chart_data.push((t, wpm_val as f64));
    }

    // Final WPM
    let final_x_max = elapsed.floor() as i64 + 1;
    let final_wpm = if elapsed <= 0.005 {
        u64::MAX
    } else {
        ((total_correct_chars as f64 * 12.0 / final_x_max as f64).ceil()) as u64
    };

    // Accuracy
    let acc = if total_typed_chars == 0 {
        100u64
    } else {
        (total_correct_chars as f64 / total_typed_chars as f64 * 100.0).round() as u64
    };

    let sd = compute_std_dev(&chart_data);

    TestResult::Completed {
        wpm: final_wpm,
        acc,
        sd,
        data: chart_data,
        elapsed,
    }
}

fn count_correct(typed: &str, expected: &str) -> usize {
    typed.chars().zip(expected.chars())
        .filter(|(t, e)| t == e)
        .count()
}

fn compute_std_dev(data: &[(f64, f64)]) -> f64 {
    if data.len() < 2 {
        return 0.0;
    }
    let wpms: Vec<f64> = data.iter().map(|(_, w)| *w).collect();
    let mean = wpms.iter().sum::<f64>() / wpms.len() as f64;
    let var = wpms.iter().map(|w| (w - mean).powi(2)).sum::<f64>() / wpms.len() as f64;
    (var.sqrt() * 100.0).round() / 100.0
}

fn show_results(
    screen: &mut Screen,
    data: &[(f64, f64)],
    wpm: u64,
    acc: u64,
    sd: f64,
) -> ResultAction {
