    crate::ui::render_chart(screen, data, tw, th, wpm, acc, sd);

    loop {
        if let Some(key) = read_key() {
            match key {
                Key::Char('r') => return ResultAction::Retry,
                Key::Char('n') => return ResultAction::New,
                Key::Escape => return ResultAction::Escape,
                _ => {}
            }
        }
    }
}

fn log_result(config: &Config, wpm: u64, acc: u64, sd: f64, elapsed: f64) {
    use std::fs::{OpenOptions, create_dir_all};
    use std::io::Write;

    let home = std::env::var("HOME").unwrap_or_default();
    let xdg_config = std::env::var("XDG_CONFIG_HOME")
        .unwrap_or_else(|_| format!("{}/.config", home));
    let log_dir = format!("{}/thokr", xdg_config);

    if create_dir_all(&log_dir).is_err() {
        return;
    }

    let log_path = format!("{}/log.csv", log_dir);

    let needs_header = !std::path::Path::new(&log_path).exists();

    if let Ok(mut file) = OpenOptions::new().create(true).append(true).open(&log_path) {
        if needs_header {
            let _ = writeln!(file, "date,num_words,num_secs,elapsed_secs,wpm,accuracy,std_dev");
        }

        let date = get_date_string();
        let wpm_str = if wpm == u64::MAX { "inf".to_string() } else { wpm.to_string() };
        let secs_str = config.secs.map(|s| format!("{:.2}", s)).unwrap_or_default();
        let elapsed_str = format!("{:.2}", elapsed);

        let _ = writeln!(
            file,
            "{},{},{},{},{},{},{:.2}",
            date, config.words, secs_str, elapsed_str, wpm_str, acc, sd
        );
    }
}

fn get_date_string() -> String {
    extern "C" {
        fn time(t: *mut i64) -> i64;
        fn localtime(t: *const i64) -> *mut std::ffi::c_void;
        fn strftime(s: *mut u8, max: usize, format: *const u8, tm: *const std::ffi::c_void) -> usize;
    }

    unsafe {
        let mut t: i64 = 0;
        time(&mut t);
        let tm = localtime(&t);
        let mut buf = vec![0u8; 64];
        let fmt = b"%a %b %e %H:%M:%S %Y\0";
        let n = strftime(buf.as_mut_ptr(), 64, fmt.as_ptr(), tm);
        if n > 0 {
            String::from_utf8_lossy(&buf[..n]).trim().to_string()
        } else {
            "unknown date".to_string()
        }
    }
}
