    pub cell_height: usize,
    pixels: Vec<u8>, // [pixel_y * (cell_width*2) + pixel_x]
    pixel_width: usize,
    pixel_height: usize,
}

impl Canvas {
    pub fn new(cell_width: usize, cell_height: usize) -> Self {
        let pw = cell_width * 2;
        let ph = cell_height * 4;
        Canvas {
            cell_width,
            cell_height,
            pixels: vec![0u8; pw * ph],
            pixel_width: pw,
            pixel_height: ph,
        }
    }

    fn set_pixel(&mut self, px: i64, py: i64) {
        if px >= 0 && py >= 0 && (px as usize) < self.pixel_width && (py as usize) < self.pixel_height {
            self.pixels[py as usize * self.pixel_width + px as usize] = 1;
        }
    }

    fn get_pixel(&self, px: usize, py: usize) -> bool {
        px < self.pixel_width && py < self.pixel_height &&
        self.pixels[py * self.pixel_width + px] != 0
    }

    // Draw Bresenham line in pixel coords
    // y=0 is TOP, y=pixel_height-1 is BOTTOM
    fn bresenham_line(&mut self, mut x0: i64, mut y0: i64, x1: i64, y1: i64) {
        let dx = (x1 - x0).unsigned_abs() as i64;
        let dy = (y1 - y0).unsigned_abs() as i64;
        let sx: i64 = if x0 < x1 { 1 } else { -1 };
        let sy: i64 = if y0 < y1 { 1 } else { -1 };
        let mut err = dx - dy;

        loop {
            self.set_pixel(x0, y0);
            if x0 == x1 && y0 == y1 {
                break;
            }
            let e2 = 2 * err;
            if e2 > -dy {
                err -= dy;
                x0 += sx;
            }
            if e2 < dx {
                err += dx;
                y0 += sy;
            }
        }
    }

    // Draw a line from (x1,y1) to (x2,y2) in normalized coords [0,1]×[0,1]
    // y=0 is BOTTOM of chart (low WPM), y=1 is TOP (high WPM)
    pub fn draw_line(&mut self, x1: f64, y1: f64, x2: f64, y2: f64) {
        let pw = self.pixel_width as f64;
        let ph = self.pixel_height as f64;

        // x normalized [0,1] → pixel [0, pw-1]
        // y normalized [0,1] (0=bottom, 1=top) → pixel [ph-1, 0]
        let px1 = (x1.clamp(0.0, 1.0) * (pw - 1.0)).round() as i64;
        let py1 = ((1.0 - y1.clamp(0.0, 1.0)) * (ph - 1.0)).round() as i64;
        let px2 = (x2.clamp(0.0, 1.0) * (pw - 1.0)).round() as i64;
        let py2 = ((1.0 - y2.clamp(0.0, 1.0)) * (ph - 1.0)).round() as i64;

        self.bresenham_line(px1, py1, px2, py2);
    }

    pub fn render(&self) -> Vec<Vec<char>> {
        let mut result = vec![vec![' '; self.cell_width]; self.cell_height];
        for cy in 0..self.cell_height {
            for cx in 0..self.cell_width {
                let mut dots = 0u8;
                for row in 0..4usize {
                    for col in 0..2usize {
                        let px = cx * 2 + col;
                        let py = cy * 4 + row;
                        if self.get_pixel(px, py) {
                            dots |= 1 << dot_bit(col, row);
                        }
                    }
                }
                result[cy][cx] = if dots == 0 {
                    ' '
                } else {
                    char::from_u32(BRAILLE_BASE + dots as u32).unwrap_or(' ')
                };
            }
        }
        result
    }
}

pub fn render_chart(
    screen: &mut Screen,
    data: &[(f64, f64)],
    term_width: u16,
    term_height: u16,
    wpm: u64,
    acc: u64,
    sd: f64,
) {
    let tw = term_width as usize;
    let th = term_height as usize;

    if th < 10 || tw < 20 {
        return;
    }

    // Get max WPM for y-axis
    let max_wpm_val = if data.is_empty() {
        0u64
    } else {
        data.iter()
            .map(|(_, w)| if *w > 1e15 { 0u64 } else { *w as u64 })
            .max()
            .unwrap_or(0)
    };

    let max_wpm_str = if wpm == u64::MAX {
        "inf".to_string()
    } else {
        format!("{}", max_wpm_val)
    };

    let y_label_width = 5 + max_wpm_str.len(); // before the │ char

    // chart_width = terminal width - y_label_width - 1 (for │)
    let chart_width = if tw > y_label_width + 1 {
        tw - y_label_width - 1
    } else {
        1
    };

    // Chart rows:
    // Row 1,2: blank
    // Row 3: top border (max_wpm│wpm + data row 0)
    // Row 4 to th-8: data rows 1 to th-10
    // Row th-7: bottom border (0│  seconds...)
    // Row th-6: └────────
    // Row th-5: x-axis labels
    // Row th-4: blank
    // Row th-3: summary
    // Row th-2: blank
    // Row th-1: keys

    // chart_inner_height = number of cells for data area
    // = th - 9 cells (rows 3 through th-7 = th-7-3+1 = th-9 rows)
    let chart_rows = if th >= 9 { th - 9 } else { 1 };
    // But row 3 and row th-7 are border rows, so inner data = chart_rows - 2
    // Actually: row 3 has TOP label + first braille row
    //           rows 4..th-8 have inner data
    //           row th-7 has BOTTOM label
    // So canvas_height = chart_rows cells total (including borders at row 3 and th-7)
    let canvas_height = chart_rows; // cells = each cell is 4 pixels tall

    // x-axis setup
    let x_max = if data.is_empty() {
        1.0f64
    } else {
        let last_t = data.last().unwrap().0;
        (last_t.floor() as i64 + 1) as f64
    };
    let x_min = 1.0f64;

    // y-axis setup  
    let y_max = max_wpm_val as f64;

    // Create canvas
    let mut canvas = Canvas::new(chart_width, canvas_height);

    // Draw data
    if !data.is_empty() && y_max > 0.0 {
        let x_range = if x_max > x_min { x_max - x_min } else { 1.0 };

        if data.len() == 1 {
            // Single point: draw horizontal line from left to point
            let (t, y) = data[0];
            let nx = ((t - x_min) / x_range).clamp(0.0, 1.0);
            let ny = (y / y_max).clamp(0.0, 1.0);
            canvas.draw_line(0.0, ny, nx, ny);
        } else {
            for i in 0..data.len()-1 {
                let (t1, y1) = data[i];
                let (t2, y2) = data[i+1];
                let nx1 = ((t1 - x_min) / x_range).clamp(0.0, 1.0);
                let ny1 = (y1 / y_max).clamp(0.0, 1.0);
                let nx2 = ((t2 - x_min) / x_range).clamp(0.0, 1.0);
                let ny2 = (y2 / y_max).clamp(0.0, 1.0);
                canvas.draw_line(nx1, ny1, nx2, ny2);
            }
        }
    }

    let chart_chars = canvas.render();

    // Clear screen
    screen.clear();

    // Row 3: top label + first chart row
    {
        let row = 3u16;
        screen.move_to(row, 1);
        // Write max_wpm right-justified in y_label_width
        let label = format!("{:>width$}", max_wpm_str, width = y_label_width);
        screen.write_str(&label);
        screen.write_str("│wpm");
        if !chart_chars.is_empty() {
            let row_str: String = chart_chars[0].iter().collect();
            screen.write_str(&row_str);
        }
    }

    // Rows 4 to (3 + canvas_height - 2): middle chart rows
    for i in 1..canvas_height.saturating_sub(1) {
        let row = (3 + i) as u16;
        screen.move_to(row, 1);
        screen.write_str(&" ".repeat(y_label_width));
        screen.write_str("│");
        if i < chart_chars.len() {
            let row_str: String = chart_chars[i].iter().collect();
            screen.write_str(&row_str);
        }
    }

    // Row th-7: bottom border with "0" and "seconds"
    if canvas_height >= 2 {
        let row = (3 + canvas_height - 1) as u16;
        screen.move_to(row, 1);
        let zero_pad = "0".to_string() + &" ".repeat(max_wpm_str.len().saturating_sub(1));
        let label = format!("     {}", zero_pad);
        screen.write_str(&label);
        screen.write_str("│");
        let seconds_label = "seconds";
        if chart_width > seconds_label.len() {
            let spaces = chart_width - seconds_label.len();
            screen.write_str(&" ".repeat(spaces));
        }
        screen.write_str(seconds_label);
    }

    // Row th-6: separator
    {
        let row = (th - 5) as u16; // th-6 in 1-indexed
        screen.move_to(row, 1);
        screen.write_str(&" ".repeat(y_label_width));
        screen.write_str("└");
        screen.write_str(&"─".repeat(chart_width));
    }

    // Row th-5: x-axis labels
    {
        let row = (th - 4) as u16;
        screen.move_to(row, 1);
        screen.write_str(&" ".repeat(y_label_width));
        screen.write_str("1");

        let x_label = format!("{:.2}", x_max);
        if chart_width > x_label.len() + 1 {
            let spaces = chart_width - x_label.len() - 1;
            screen.write_str(&" ".repeat(spaces));
            screen.write_str(&x_label);
        }
    }

    // Row th-3: blank (already cleared)

    // Row th-2: summary stats
    {
        let row = (th - 2) as u16;
        let wpm_str = if wpm == u64::MAX { "inf".to_string() } else { format!("{}", wpm) };
        let summary = format!("{} wpm   {}% acc   {:.2} sd", wpm_str, acc, sd);
        let col = if tw > summary.len() {
            (tw - summary.len()) / 2 + 1
        } else {
            1
        };
        screen.move_to(row, col as u16);
        screen.write_str(&summary);
    }

    // Row th (last visible): keys
    {
        let row = th as u16;
        screen.move_to(row, 1);
        screen.write_str("     (r)etry / (n)ew / (esc)ape");
    }

    screen.flush();
}

pub fn render_test(
    screen: &mut Screen,
    words: &[String],
    typed: &[String],
    current_input: &str,
    timer: Option<f64>,
    term_width: u16,
    term_height: u16,
) {
    let tw = term_width as usize;
    let th = term_height as usize;

    // Build the full expected text
    let full_text: Vec<&str> = words.iter().map(|s| s.as_str()).collect();

    // Wrap text to fit terminal width (with margins)
    let max_width = tw.saturating_sub(4);
    let lines = wrap_words(&full_text, max_width);

    // Vertical centering
    let n_lines = lines.len();

    let content_height = n_lines + if timer.is_some() { 2 } else { 0 };
    let start_row = if th > content_height {
        (th - content_height) / 2 + 1
    } else {
        1
    };

    screen.clear();

    // Timer display
    let text_start_row = if let Some(remaining) = timer {
        let timer_str = format!("{:.1}", remaining);
        let timer_col = if tw > timer_str.len() { (tw - timer_str.len()) / 2 + 1 } else { 1 };
        screen.move_to(start_row as u16, timer_col as u16);
        screen.write_str(&timer_str);
        start_row + 2
    } else {
        start_row
    };

    // Build the typed sequence with character-level info
    // typed[] has completed words, current_input is the current word being typed
    // We track position in the expected text

    // Build expected char sequence with positions
    // For each word: word_chars + space (except last word)
    let mut expected: Vec<char> = Vec::new();
    for (i, word) in words.iter().enumerate() {
        for c in word.chars() {
            expected.push(c);
        }
        if i < words.len() - 1 {
            expected.push(' ');
        }
    }

    // Build typed char sequence
    let mut typed_chars: Vec<char> = Vec::new();
    for (i, tw) in typed.iter().enumerate() {
        for c in tw.chars() {
            typed_chars.push(c);
        }
        // Add space after each typed word (before cursor word)
        if i < typed.len() {
            typed_chars.push(' ');
        }
    }
    for c in current_input.chars() {
        typed_chars.push(c);
    }

    let cursor_pos = typed_chars.len();

    // Render each line
    let mut char_offset = 0usize;
    for (line_idx, line_words) in lines.iter().enumerate() {
        let line_str = line_words.join(" ");
        let row = (text_start_row + line_idx) as u16;
        let col = if tw > line_str.len() { (tw - line_str.len()) / 2 + 1 } else { 1 };

        screen.move_to(row, col as u16);

        // Render each character with color
        let line_chars: Vec<char> = line_str.chars().collect();
        for (i, &c) in line_chars.iter().enumerate() {
            let pos = char_offset + i;

            if pos < typed_chars.len() {
                // Typed character
                if pos < expected.len() && typed_chars[pos] == expected[pos] {
                    screen.set_green();
                    screen.write_str(&c.to_string());
                    screen.set_normal();
                } else {
                    screen.set_red();
                    screen.write_str(&c.to_string());
                    screen.set_normal();
                }
            } else if pos == cursor_pos {
                // Cursor position
                screen.set_underline();
                screen.write_str(&c.to_string());
                screen.set_normal();
            } else {
                screen.write_str(&c.to_string());
            }
        }

        char_offset += line_str.len() + 1; // +1 for newline/space between lines
    }

    screen.flush();
}

// Wrap words into lines of at most max_width chars
fn wrap_words<'a>(words: &[&'a str], max_width: usize) -> Vec<Vec<&'a str>> {
    if max_width == 0 || words.is_empty() {
        return vec![words.to_vec()];
    }

    let mut lines: Vec<Vec<&str>> = Vec::new();
    let mut current_line: Vec<&str> = Vec::new();
    let mut current_len = 0usize;

    for &word in words {
        let word_len = word.len();
        if current_line.is_empty() {
            current_line.push(word);
            current_len = word_len;
        } else if current_len + 1 + word_len <= max_width {
            current_line.push(word);
            current_len += 1 + word_len;
        } else {
            lines.push(current_line);
            current_line = vec![word];
            current_len = word_len;
        }
    }

    if !current_line.is_empty() {
        lines.push(current_line);
    }

    lines
}
