pub fn read_key() -> Option<Key> {
    let c = read_byte()?;

    match c {
        27 => {
            // ESC - might be escape sequence
            if has_input_within(50) {
                match read_byte() {
                    Some(b'[') => {
                        if has_input_within(50) {
                            match read_byte() {
                                Some(b'A') => return Some(Key::Up),
                                Some(b'B') => return Some(Key::Down),
                                Some(b'C') => return Some(Key::Right),
                                Some(b'D') => return Some(Key::Left),
                                _ => {}
                            }
                        }
                    }
                    _ => {}
                }
            }
            Some(Key::Escape)
        }
        127 | 8 => Some(Key::Backspace),
        13 | 10 => Some(Key::Enter),
        c if c >= 32 => Some(Key::Char(c as char)),
        _ => None,
    }
}

