class Canvas:
    def __init__(self, cw, ch):
        self.cw = cw
        self.ch = ch
        self.pw = cw*2
        self.ph = ch*4
        self.pixels = [[False]*(cw*2) for _ in range(ch*4)]

    def set_pixel(self, x, y):
        if 0 <= x < self.pw and 0 <= y < self.ph:
            self.pixels[y][x] = True

    def bresenham(self, x0, y0, x1, y1):
        dx = abs(x1-x0)
        dy = abs(y1-y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx - dy
        while True:
            self.set_pixel(x0, y0)
            if x0 == x1 and y0 == y1:
                break
            e2 = 2*err
            if e2 > -dy:
                err -= dy
                x0 += sx
            if e2 < dx:
                err += dx
                y0 += sy

    def draw_line(self, x1, y1, x2, y2):
