    if intervals.len() < 2 {
        return 0.0;
    }
    let mean = intervals.iter().sum::<f64>() / intervals.len() as f64;
    let var = intervals.iter().map(|i| (i - mean).powi(2)).sum::<f64>() / intervals.len() as f64;
    let std = var.sqrt();
    // Round to 1 decimal place, then display with 2dp
    (std * 10.0).round() / 10.0
}'''

