    // Compute intervals using floor(t) differences
    let floored: Vec<f64> = word_times.iter().map(|&t| t.floor()).collect();
    let mut intervals: Vec<f64> = Vec::new();
    let mut prev = 0.0f64;
    for &ft in &floored {
        intervals.push(ft - prev);
        prev = ft;
    }
    if intervals.len() < 2 {
        return 0.0;
    }
    let mean = intervals.iter().sum::<f64>() / intervals.len() as f64;
    let var = intervals.iter().map(|i| (i - mean).powi(2)).sum::<f64>() / intervals.len() as f64;
    let std = var.sqrt();
    // Round to 1 decimal place, then display with 2dp
    (std * 10.0).round() / 10.0
